export function t(key, lang = 'en') {
    const translation = translations[key];
    if (!translation) {
        // Safe fallback only in dev
        // console.warn(`Translation missing for key: ${key}`);
        return key;
    }

    if (translation[lang]) {
        return translation[lang];
    }

    // Default to English
    return translation['en'] || key;
}

export function getCurrentLanguage() {
    if (typeof window !== 'undefined') {
        return localStorage.getItem('krishi_lang') || 'en';
    }
    return 'en';
}

export function setCurrentLanguage(lang) {
    if (typeof window !== 'undefined') {
        localStorage.setItem('krishi_lang', lang);
    }
}

export default { t, translations, SUPPORTED_LANGUAGES, getCurrentLanguage, setCurrentLanguage };
